   553  static int
   554  _parse_safe_contents(ASN1_TYPE sc, const char *sc_name,
   555                       gnutls_pkcs12_bag_t bag)
   556  {
   557          gnutls_datum_t content = { NULL, 0 };
   558          int result;
   559
   560          /* Step 1. Extract the content.
  1510   * This function parses a PKCS12 structure in @pkcs12 and extracts the
  1511   * private key, the corresponding certificate chain, any additional
  1512   * certificates and a CRL. The structures in @key, @chain @crl, and @extra_certs
  1513   * must not be initialized.
  1514   *
  1515   * The @extra_certs and @extra_certs_len parameters are optional
  1516   * and both may be set to %NULL. If either is non-%NULL, then both must
  1517   * be set. The value for @extra_certs is allocated
  1518   * using gnutls_malloc().
  1519   *
  1520   * Encrypted PKCS12 bags and PKCS8 private keys are supported, but
  1521   * only with password based security and the same password for all
  1522   * operations.
  1523   *
  1524   * Note that a PKCS12 structure may contain many keys and/or certificates,
  1525   * and there is no way to identify which key/certificate pair you want.
  1526   * For this reason this function is useful for PKCS12 files that contain
  1527   * only one key/certificate pair and/or one CRL.
  1528   *
  1529   * If the provided structure has encrypted fields but no password
  1530   * is provided then this function returns %GNUTLS_E_DECRYPTION_FAILED.
  1531   *
  1532   * Note that normally the chain constructed does not include self signed
  1533   * certificates, to comply with TLS' requirements. If, however, the flag
  1534   * %GNUTLS_PKCS12_SP_INCLUDE_SELF_SIGNED is specified then
  1535   * self signed certificates will be included in the chain.
  1536   *
  1537   * Prior to using this function the PKCS #12 structure integrity must
  1538   * be verified using gnutls_pkcs12_verify_mac().
  1539   *
  1540   * Returns: On success, %GNUTLS_E_SUCCESS (0) is returned, otherwise a
  1541   *   negative error value.
  1542   *
  1543   * Since: 3.1.0
  1544   **/
  1545  int
  1546  gnutls_pkcs12_simple_parse(gnutls_pkcs12_t p12,
  1547                             const char *password,
  1548                             gnutls_x509_privkey_t * key,
  1549                             gnutls_x509_crt_t ** chain,
  1550                             unsigned int *chain_len,
  1551                             gnutls_x509_crt_t ** extra_certs,
  1552                             unsigned int *extra_certs_len,
  1553                             gnutls_x509_crl_t * crl, unsigned int flags)
  1554  {
  1555          gnutls_pkcs12_bag_t bag = NULL;
  1556          gnutls_x509_crt_t *_extra_certs = NULL;
  1557          unsigned int _extra_certs_len = 0;
  1558          gnutls_x509_crt_t *_chain = NULL;
  1559          unsigned int _chain_len = 0;
  1560          int idx = 0;
  1561          int ret;
  1562          size_t cert_id_size = 0;
  1563          size_t key_id_size = 0;
  1564          uint8_t cert_id[20];
  1565          uint8_t key_id[20];
  1566          int privkey_ok = 0;
  1567          unsigned int i;
  1568          int elements_in_bag;
  1569
  1570          *key = NULL;
  1571
  1572          if (crl)
  1573                  *crl = NULL;
  1574
  1575          /* find the first private key */
  1576          for (;;) {
  1577
  1578                  ret = gnutls_pkcs12_bag_init(&bag);
  1579                  if (ret < 0) {
  1580                          bag = NULL;
  1581                          gnutls_assert();
  1582                          goto done;
  1583                  }
  1584
  1585                  ret = gnutls_pkcs12_get_bag(p12, idx, bag);
  1586                  if (ret == GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE) {
  1587                          gnutls_pkcs12_bag_deinit(bag);
  1588                          bag = NULL;
  1589                          break;
  1590                  }
  1591                  if (ret < 0) {
  1592                          gnutls_assert();
  1593                          goto done;
  1594                  }
  1595
  1596                  ret = gnutls_pkcs12_bag_get_type(bag, 0);
  1597                  if (ret < 0) {
  1598                          gnutls_assert();
  1599                          goto done;
  1600                  }
  1601
  1602                  if (ret == GNUTLS_BAG_ENCRYPTED) {
  1603                          if (password == NULL) {
  1604                                  ret =
  1605                                      gnutls_assert_val
  1606                                      (GNUTLS_E_DECRYPTION_FAILED);
  1607                                  goto done;
  1608                          }
  1609
  1610                          ret = gnutls_pkcs12_bag_decrypt(bag, password);
  1611                          if (ret < 0) {
  1612                                  gnutls_assert();
  1613                                  goto done;
  1614                          }
  1615                  }
  1616
  1617                  elements_in_bag = gnutls_pkcs12_bag_get_count(bag);
  1618                  if (elements_in_bag < 0) {
  1619                          gnutls_assert();
  1620                          goto done;
  1621                  }
  1622
  1623                  for (i = 0; i < (unsigned)elements_in_bag; i++) {
  1624                          int type;
  1625                          gnutls_datum_t data;
  1626
  1627                          type = gnutls_pkcs12_bag_get_type(bag, i);
  1628                          if (type < 0) {
  1629                                  gnutls_assert();
  1630                                  goto done;
  1631                          }
  1632
  1633                          ret = gnutls_pkcs12_bag_get_data(bag, i, &data);
  1634                          if (ret < 0) {
  1635                                  gnutls_assert();
  1636                                  goto done;
  1637                          }
  1638
  1639                          switch (type) {
  1640                          case GNUTLS_BAG_PKCS8_ENCRYPTED_KEY:
  1641                                  if (password == NULL) {
  1642                                          ret =
  1643                                              gnutls_assert_val
  1644                                              (GNUTLS_E_DECRYPTION_FAILED);
  1645                                          goto done;
  1646                                  }
  1647
  1648                                  FALLTHROUGH;
  1649                          case GNUTLS_BAG_PKCS8_KEY:
  1650                                  if (*key != NULL) {     /* too simple to continue */
  1651                                          gnutls_assert();
  1652                                          break;
  1653                                  }
  1654
  1655                                  ret = gnutls_x509_privkey_init(key);
  1656                                  if (ret < 0) {
  1657                                          gnutls_assert();
  1658                                          goto done;
  1659                                  }
  1660
  1661                                  ret = gnutls_x509_privkey_import_pkcs8
  1662                                      (*key, &data, GNUTLS_X509_FMT_DER,
  1663                                       password,
  1664                                       type ==
  1665                                       GNUTLS_BAG_PKCS8_KEY ?
  1666                                       GNUTLS_PKCS_PLAIN : 0);
  1667                                  if (ret < 0) {
  1668                                          gnutls_assert();
  1669                                          goto done;
  1670                                  }
  1671
  1672                                  key_id_size = sizeof(key_id);
  1673                                  ret =
  1674                                      gnutls_x509_privkey_get_key_id(*key, 0,
  1675                                                                     key_id,
  1676                                                                     &key_id_size);
  1677                                  if (ret < 0) {
  1678                                          gnutls_assert();
  1679                                          goto done;
  1680                                  }
  1681
  1682                                  privkey_ok = 1; /* break */
  1683                                  break;
  1684                          default:
  1685                                  break;
  1686                          }
  1687                  }
  1688
  1689                  idx++;
  1690                  gnutls_pkcs12_bag_deinit(bag);
  1691                  bag = NULL;
  1692
  1693                  if (privkey_ok != 0)    /* private key was found */
  1694                          break;
  1695          }
  1696
  1697          if (privkey_ok == 0) {  /* no private key */
  1698                  gnutls_assert();
  1699                  return GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE;
  1700          }
  1701
  1702          /* now find the corresponding certificate
  1703           */
  1704          idx = 0;
  1705          bag = NULL;
  1706          for (;;) {
  1707                  ret = gnutls_pkcs12_bag_init(&bag);
  1708                  if (ret < 0) {
  1709                          bag = NULL;
  1710                          gnutls_assert();
  1711                          goto done;
  1712                  }
  1713
  1714                  ret = gnutls_pkcs12_get_bag(p12, idx, bag);
  1715                  if (ret == GNUTLS_E_REQUESTED_DATA_NOT_AVAILABLE) {
  1716                          gnutls_pkcs12_bag_deinit(bag);
  1717                          bag = NULL;
  1718                          break;
  1719                  }
  1720                  if (ret < 0) {
  1721                          gnutls_assert();
  1722                          goto done;
  1723                  }
  1724
  1725                  ret = gnutls_pkcs12_bag_get_type(bag, 0);
  1726                  if (ret < 0) {
  1727                          gnutls_assert();
  1728                          goto done;
  1729                  }
  1730
  1731                  if (ret == GNUTLS_BAG_ENCRYPTED) {
  1732                          ret = gnutls_pkcs12_bag_decrypt(bag, password);
  1733                          if (ret < 0) {
  1734                                  gnutls_assert();
  1735                                  goto done;
  1736                          }
  1737                  }
  1738
  1739                  elements_in_bag = gnutls_pkcs12_bag_get_count(bag);
  1740                  if (elements_in_bag < 0) {
  1741                          gnutls_assert();
  1742                          goto done;
  1743                  }
  1744
  1745                  for (i = 0; i < (unsigned)elements_in_bag; i++) {
  1746                          int type;
  1747                          gnutls_datum_t data;
  1748                          gnutls_x509_crt_t this_cert;
  1749
  1750                          type = gnutls_pkcs12_bag_get_type(bag, i);
  1751                          if (type < 0) {
  1752                                  gnutls_assert();
  1753                                  goto done;
  1754                          }
  1755
  1756                          ret = gnutls_pkcs12_bag_get_data(bag, i, &data);
  1757                          if (ret < 0) {
  1758                                  gnutls_assert();
  1759                                  goto done;
  1760                          }
  1761
  1762                          switch (type) {
  1763                          case GNUTLS_BAG_CERTIFICATE:
  1764                                  ret = gnutls_x509_crt_init(&this_cert);
  1765                                  if (ret < 0) {
  1766                                          gnutls_assert();
  1767                                          goto done;
  1768                                  }
  1769
  1770                                  ret =
  1771                                      gnutls_x509_crt_import(this_cert,
  1772                                                             &data,
  1773                                                             GNUTLS_X509_FMT_DER);
  1774                                  if (ret < 0) {
  1775                                          gnutls_assert();
  1776                                          gnutls_x509_crt_deinit(this_cert);
  1777                                          this_cert = NULL;
  1778                                          goto done;
  1779                                  }
  1780
  1781                                  /* check if the key id match */
  1782                                  cert_id_size = sizeof(cert_id);
  1783                                  ret =
  1784                                      gnutls_x509_crt_get_key_id(this_cert,
  1785                                                                 0, cert_id,
  1786                                                                 &cert_id_size);
  1787                                  if (ret < 0) {
  1788                                          gnutls_assert();
  1789                                          gnutls_x509_crt_deinit(this_cert);
  1790                                          this_cert = NULL;
  1791                                          goto done;
